import { app, BrowserWindow, Tray, Menu, nativeImage } from 'electron';

/** Ícono generado (anillo cian) embebido para no depender de assets externos. */
const TRAY_ICON_BASE64 =
  '';

/** Alternativa generada por código (anillo cian sobre fondo transparente) si falla el embebido. */
function buildFallbackIcon() {
  const size = 64;
  const img = nativeImage.createEmpty();
  try {
    const { createCanvas } = require('canvas') as any; // opcional, no instalado
    void createCanvas;
  } catch {}
  return img;
}

export function createTray(win: BrowserWindow, onToggle: () => void, onQuit: () => void): Tray {
  let icon = nativeImage.createFromDataURL(`data:image/png;base64,${TRAY_ICON_BASE64}`);
  if (icon.isEmpty()) {
    icon = buildFallbackIcon();
  }

  const tray = new Tray(icon);
  tray.setToolTip('IA-companion-GS — Asistente de escritorio');

  const menu = Menu.buildFromTemplate([
    {
      label: 'Mostrar / ocultar asistente',
      click: onToggle,
    },
    { type: 'separator' },
    {
      label: 'Salir',
      click: onQuit,
    },
  ]);

  tray.setContextMenu(menu);
  tray.on('click', () => tray.popUpContextMenu());

  // Clic左右 en icono también alterna
  tray.on('double-click', onToggle);

  return tray;
}

import { BrowserWindow, Tray, Menu, nativeImage } from 'electron';

/** Ícono de bandeja (anillo cian sobre fondo transparente) embebido para no depender de assets externos. */
const TRAY_ICON_BASE64 =
  '';

/**
 * Tray del asistente: acceso permanente desde la bandeja del sistema.
 */
export function createTray(win: BrowserWindow, onToggle: () => void, onQuit: () => void): Tray {
  const icon = nativeImage.createFromDataURL(`data:image/png;base64,${TRAY_ICON_BASE64}`);
  const tray = new Tray(icon);
  tray.setToolTip('IA-companion-GS — Asistente de escritorio');

  const menu = Menu.buildFromTemplate([
    { label: 'Mostrar / ocultar asistente', click: onToggle },
    { type: 'separator' },
    { label: 'Salir', click: onQuit },
  ]);

  tray.setContextMenu(menu);
  tray.on('double-click', onToggle);

  return tray;
}

