$src = New-Object System.Drawing.Bitmap($srcPath)
$w = $src.Width; $h = $src.Height

# --- Extraer bytes (BGRA) ---
$rect = New-Object System.Drawing.Rectangle(0, 0, $w, $h)
$data = $src.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadWrite, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$bytes = New-Object byte[] ($w * $h * 4)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)

$idx = { param($x, $y) ($y * $w + $x) * 4 }

# --- Flood fill desde bordes sobre pixeles "tablero" (gris neutro claro) ---
$visited = New-Object bool[] ($w * $h)
$queue = New-Object 'System.Collections.Generic.Queue[object]'
function Is-BoardPixel([byte[]]$b, [int]$i) {
    $bl = $b[$i]; $g = $b[$i + 1]; $r = $b[$i + 2]
    $mx = [Math]::Max($r, [Math]::Max($g, $bl))
    $mn = [Math]::Min($r, [Math]::Min($g, $bl))
    $lum = ($r + $g + $bl) / 3
    return (($mx - $mn) -le 18) -and ($lum -ge 200)
}
for ($x = 0; $x -lt $w; $x++) {
    foreach ($y in @(0, $h - 1)) {
        $i = $y * $w + $x
        if (-not $visited[$i] -and (Is-BoardPixel $bytes ($i * 4))) { $visited[$i] = $true; $queue.Enqueue($i) }
    }
}
for ($y = 0; $y -lt $h; $y++) {
