        if (-not $visited[$i] -and (Is-BoardPixel $bytes ($i * 4))) { $visited[$i] = $true; $queue.Enqueue($i) }
    }
}
while ($queue.Count -gt 0) {
    $i = $queue.Dequeue()
    $bytes[($i * 4) + 3] = 0  # alpha 0
    $x = $i % $w; $y = [Math]::Floor($i / $w)
    foreach ($n in @(@($x - 1, $y), @($x + 1, $y), @($x, $y - 1), @($x, $y + 1))) {
        $nx = $n[0]; $ny = $n[1]
