    $g.DrawImage($bitmap, (New-Object System.Drawing.Rectangle(0, 0, $outSize, $outSize)), $sq, [System.Drawing.GraphicsUnit]::Pixel)
    $g.Dispose()
    $out.Save($outPath, [System.Drawing.Imaging.ImageFormat]::Png)
    $out.Dispose()
}

# --- Icono cuadrado del monograma (sin wordmark) ---
$markH = 770 - $minY
$markW = ($maxX - $minX)
if ($markH -gt 0 -and ($maxY - $minY) -gt 0) {
    # mark aproximado: desde minY hasta el fin del monograma (~antes del wordmark)
    $monogramBottom = $minY + $markH
    Save-Cropped $src $minX $minY ($maxX - $minX) $monogramBottom "$buildDir\icon.png" 256
    Save-Cropped $src $minX $minY ($maxX - $minX) $monogramBottom "$assetsDir\icon-mark.png" 128
}

# --- Logo completo a 320px de ancho para la pestaña Acerca de ---
$scale = 320.0 / $w
$outFull = New-Object System.Drawing.Bitmap(320, [int]($h * $scale))
$gf = [System.Drawing.Graphics]::FromImage($outFull)
$gf.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
$gf.SmoothingMode = 'AntiAlias'
$gf.DrawImage($src, (New-Object System.Drawing.Rectangle(0, 0, $outFull.Width, $outFull.Height)), (New-Object System.Drawing.Rectangle(0, 0, $w, $h)), [System.Drawing.GraphicsUnit]::Pixel)
$gf.Dispose()
$outFull.Save("$assetsDir\logo.png", [System.Drawing.Imaging.ImageFormat]::Png)
$outFull.Dispose()

# --- .ico (32px) para futuro empaquetado ---
$iconBmp = New-Object System.Drawing.Bitmap("$buildDir\icon.png")
$hicon = $iconBmp.GetHicon()
$icon = [System.Drawing.Icon]::FromHandle($hicon)
$fs = [System.IO.File]::Create("$buildDir\icon.ico")
$icon.Save($fs)
$fs.Dispose()
[void][System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
$icon.Dispose(); $iconBmp.Dispose()

$src.Dispose()
Write-Host "OK: generados build\ia-logo-full.png, build\icon.png, build\icon.ico, assets\logo.png, assets\icon-mark.png"

