Add-Type -AssemblyName System.Drawing
$ErrorActionPreference = 'Stop'

$srcPath = 'C:\Users\Administrator\Downloads\fDa3R.jpg'
$buildDir = 'C:\Users\Administrator\Trabajo\IA-companion-GS\build'
$assetsDir = 'C:\Users\Administrator\Trabajo\IA-companion-GS\src\renderer\assets'
New-Item -ItemType Directory -Force -Path $buildDir, $assetsDir | Out-Null

$src = New-Object System.Drawing.Bitmap($srcPath)
$w = $src.Width; $h = $src.Height
$rect = New-Object System.Drawing.Rectangle(0, 0, $w, $h)

# --- Leer bytes (BGRA) ---
$data = $src.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$bytes = New-Object byte[] ($w * $h * 4)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)
$src.UnlockBits($data)

# total pixels helper
function Get-Spread([byte[]]$b, [int]$o, [ref]$lumOut) {
    $bl = $b[$o]; $g = $b[$o + 1]; $r = $b[$o + 2]
    $mx = [Math]::Max($r, [Math]::Max($g, $bl))
    $mn = [Math]::Min($r, [Math]::Min($g, $bl))
    $lumOut.Value = ($r + $g + $bl) / 3
    return ($mx - $mn)
}

# ---------- PASO 1: flood fill desde bordes (tablero conectado al borde) ----------
$visited = New-Object bool[] ($w * $h)
$queue = New-Object 'System.Collections.Generic.Queue[int]'
function Test-Board([byte[]]$b, [int]$o) {
    $lum = 0
    $spread = Get-Spread $b $o ([ref]$lum)
    return (($spread -le 18) -and ($lum -ge 200))
}
for ($x = 0; $x -lt $w; $x++) {
    foreach ($y in @(0, ($h - 1))) {
        $i = $y * $w + $x
        if (-not $visited[$i] -and (Test-Board $bytes ($i * 4))) { $visited[$i] = $true; $queue.Enqueue($i) }
    }
}
for ($y = 0; $y -lt $h; $y++) {
    foreach ($x in @(0, ($w - 1))) {
        $i = $y * $w + $x
        if (-not $visited[$i] -and (Test-Board $bytes ($i * 4))) { $visited[$i] = $true; $queue.Enqueue($i) }
    }
}
while ($queue.Count -gt 0) {
    $i = $queue.Dequeue()
    $bytes[($i * 4) + 3] = 0
    $x = $i % $w; $y = [Math]::Floor($i / $w)
    foreach ($n in @(@(($x - 1), $y), @(($x + 1), $y), @($x, ($y - 1)), @($x, ($y + 1)))) {
        $nx = $n[0]; $ny = $n[1]
        if ($nx -ge 0 -and $nx -lt $w -and $ny -ge 0 -and $ny -lt $h) {
            $ni = $ny * $w + $nx
            if (-not $visited[$ni] -and (Test-Board $bytes ($ni * 4))) { $visited[$ni] = $true; $queue.Enqueue($ni) }
        }
    }
}

# ---------- PASO 2: proteger componentes blancos sólidos (núcleo, nodos, anillo) ----------
# Componentes conexos de pixeles "casi blanco" (spread<=10, lum>=248)
$nearWhite = New-Object bool[] ($w * $h)
$wq = New-Object 'System.Collections.Generic.Queue[int]'
function Test-NearWhite([byte[]]$b, [int]$o) {
    $lum = 0
    $spread = Get-Spread $b $o ([ref]$lum)
    return (($spread -le 10) -and ($lum -ge 248))
}
for ($i = 0; $i -lt ($w * $h); $i++) {
    if (-not $visited[$i] -and (Test-NearWhite $bytes ($i * 4))) { $nearWhite[$i] = $true }
}
$protectMinX = @{}; $protectRegionMin = New-Object int[] ($w * $h)  # label -> no (usamos listas)
$regionBoxes = New-Object 'System.Collections.Generic.List[object]'
$label = New-Object int[] ($w * $h)
$nextLabel = 1
$wq2 = New-Object 'System.Collections.Generic.Queue[int]'
for ($i = 0; $i -lt ($w * $h); $i++) {
    if ($nearWhite[$i] -and $label[$i] -eq 0) {
        $l = $nextLabel; $nextLabel++
        $label[$i] = $l
        $wq2.Enqueue($i)
        $minX = $w; $minY = $h; $maxX = 0; $maxY = 0; $count = 0
        while ($wq2.Count -gt 0) {
            $j = $wq2.Dequeue(); $count++
            $jx = $j % $w; $jy = [Math]::Floor($j / $w)
            if ($jx -lt $minX) { $minX = $jx }; if ($jx -gt $maxX) { $maxX = $jx }
            if ($jy -lt $minY) { $minY = $jy }; if ($jy -gt $maxY) { $maxY = $jy }
            foreach ($n in @(@(($jx - 1), $jy), @(($jx + 1), $jy), @($jx, ($jy - 1)), @($jx, ($jy + 1)))) {
                $nx = $n[0]; $ny = $n[1]
                if ($nx -ge 0 -and $nx -lt $w -and $ny -ge 0 -and $ny -lt $h) {
                    $nj = $ny * $w + $nx
                    if ($nearWhite[$nj] -and $label[$nj] -eq 0) { $label[$nj] = $l; $wq2.Enqueue($nj) }
                }
            }
        }
        if ($count -gt 40) { # solo protégé blobs sólidos, no píxeles aislados
            [void]$regionBoxes.Add(@{ minX = $minX; minY = $minY; maxX = $maxX; maxY = $maxY; count = $count })
        }
    }
}
Write-Host "regiones blancas protegidas: $($regionBoxes.Count)"

# ---------- PASO 3: limpieza global del tablero residual (fuera de regiones protegidas) ----------
$cleaned = 0
for ($i = 0; $i -lt ($w * $h); $i++) {
    if ($bytes[($i * 4) + 3] -eq 0) { continue }
    $x = $i % $w; $y = [Math]::Floor($i / $w)
    $inProtected = $false
    foreach ($box in $regionBoxes) {
        if ($x -ge $box.minX -and $x -le $box.maxX -and $y -ge $box.minY -and $y -le $box.maxY) { $inProtected = $true; break }
    }
    if ($inProtected) { continue }
    $lum = 0
    $spread = Get-Spread $bytes ($i * 4) ([ref]$lum)
    if (($spread -le 14) -and ($lum -ge 206)) { $bytes[($i * 4) + 3] = 0; $cleaned++ }
}
Write-Host "pixeles residuales limpiados: $cleaned"

# ---------- Bounding box y corte por filas ----------
$minX = $w; $minY = $h; $maxX = 0; $maxY = 0
$rowCounts = New-Object int[] $h
for ($y = 0; $y -lt $h; $y++) {
    $c = 0
    for ($x = 0; $x -lt $w; $x++) {
        if ($bytes[($y * $w + $x) * 4 + 3] -gt 8) { $c++ }
    }
    $rowCounts[$y] = $c
    if ($c -gt 0) {
        if ($y -lt $minY) { $minY = $y }; if ($y -gt $maxY) { $maxY = $y }
    }
}
for ($x = 0; $x -lt $w; $x++) {
    for ($y = $minY; $y -le $maxY; $y++) {
        if ($bytes[($y * $w + $x) * 4 + 3] -gt 8) { if ($x -lt $minX) { $minX = $x }; if ($x -gt $maxX) { $maxX = $x }; break }
    }
    for ($y = $maxY; $y -ge $minY; $y--) {
        if ($bytes[($y * $w + $x) * 4 + 3] -gt 8) { if ($x -lt $minX) { $minX = $x }; if ($x -gt $maxX) { $maxX = $x }; break }
    }
}
Write-Host "bbox: x=$minX..$maxX y=$minY..$maxY"

# Mayor banda horizontal vacía dentro del contenido = separación mark/wordmark
$gapStart = -1; $gapEnd = -1; $bestStart = -1; $bestLen = 0; $curStart = -1
for ($y = $minY; $y -le $maxY; $y++) {
    if ($rowCounts[$y] -lt 3) {
        if ($curStart -lt 0) { $curStart = $y }
    } else {
        if ($curStart -ge 0) {
            $len = $y - $curStart
            if ($len -gt $bestLen) { $bestLen = $len; $bestStart = $curStart; $gapEnd = $y }
            $curStart = -1
        }
    }
}
if ($bestLen -gt 5) { $gapStart = $bestStart; $markBottom = $gapStart - 1 } else { $markBottom = $maxY }
Write-Host "separador mark/wordmark: filas $gapStart..$gapEnd (largo $bestLen), mark termina en $markBottom"

# ---------- Bitmap final con alfa ----------
$outBmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$odata = $outBmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::WriteOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
[System.Runtime.InteropServices.Marshal]::Copy($bytes, 0, $odata.Scan0, $bytes.Length)
$outBmp.UnlockBits($odata)
$outBmp.Save("$buildDir\ia-logo-full.png", [System.Drawing.Imaging.ImageFormat]::Png)

function Save-Cropped([System.Drawing.Bitmap]$bitmap, [int]$cx, [int]$cy, [int]$cw, [int]$ch, [string]$outPath, [int]$outSize) {
    $square = [Math]::Max($cw, $ch)
    $pad = [int]($square * 0.08)
    $sq = New-Object System.Drawing.Rectangle(($cx - $pad), ($cy - $pad), ($square + 2 * $pad), ($square + 2 * $pad))
    $out = New-Object System.Drawing.Bitmap($outSize, $outSize)
    $g = [System.Drawing.Graphics]::FromImage($out)
    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $g.SmoothingMode = 'AntiAlias'
    $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
    $g.DrawImage($bitmap, (New-Object System.Drawing.Rectangle(0, 0, $outSize, $outSize)), $sq, [System.Drawing.GraphicsUnit]::Pixel)
    $g.Dispose()
    $out.Save($outPath, [System.Drawing.Imaging.ImageFormat]::Png)
    $out.Dispose()
}

# --- Icono: solo el monograma ---
$markH = $markBottom - $minY + 1
$markW = $maxX - $minX + 1
if ($markH -gt 0) {
    Save-Cropped $outBmp $minX $minY $markW $markH "$buildDir\icon.png" 256
    Save-Cropped $outBmp $minX $minY $markW $markH "$assetsDir\icon-mark.png" 128
}

# --- .ico para futuro empaquetado ---
$iconBmp = New-Object System.Drawing.Bitmap("$buildDir\icon.png")
$hicon = $iconBmp.GetHicon()
$icon = [System.Drawing.Icon]::FromHandle($hicon)
$fs = [System.IO.File]::Create("$buildDir\icon.ico")
$icon.Save($fs)
$fs.Dispose()
$icon.Dispose(); $iconBmp.Dispose()

# --- Logo completo (mark + wordmark) a 320px de ancho para Acerca de ---
$scale = 320.0 / $w
$outFull = New-Object System.Drawing.Bitmap(320, [int]($h * $scale))
$gf = [System.Drawing.Graphics]::FromImage($outFull)
$gf.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
$gf.SmoothingMode = 'AntiAlias'
$gf.DrawImage($outBmp, (New-Object System.Drawing.Rectangle(0, 0, $outFull.Width, $outFull.Height)), (New-Object System.Drawing.Rectangle(0, 0, $w, $h)), [System.Drawing.GraphicsUnit]::Pixel)
$gf.Dispose()
$outFull.Save("$assetsDir\logo.png", [System.Drawing.Imaging.ImageFormat]::Png)
$outFull.Dispose()

$src.Dispose()
$outBmp.Dispose()
Write-Host "OK"

