# ---------- PASO 2+3: limpieza global del tablero residual por PERIODICIDAD ----------
# El tablero alterna gris(218)/blanco(255) cada 8px: un pixel gris-claro "tablero"
# cambia de tono al mirar +-8px verticales. El nucleo blanco solido no cambia.
$cleaned = 0
for ($y = 0; $y -lt $h; $y++) {
    for ($x = 0; $x -lt $w; $x++) {
        $i = $y * $w + $x
        if ($bytes[($i * 4) + 3] -eq 0) { continue }
        $lum = 0
        $spread = Get-Spread $bytes ($i * 4) ([ref]$lum)
        if ($spread -gt 14 -or $lum -lt 206) { continue }
        # comparar con 8px vertical abajo y arriba (existiendo)
        $isChecker = $false
        if ($y + 8 -lt $h) {
            $lum2 = 0
            [void](Get-Spread $bytes ((($y + 8) * $w + $x) * 4) ([ref]$lum2))
            if ([Math]::Abs($lum - $lum2) -gt 15) { $isChecker = $true }
        }
        if (-not $isChecker -and $y - 8 -ge 0) {
            $lum2 = 0
