input.content:
Add-Type -AssemblyName System.Drawing
$ErrorActionPreference = 'Stop'

$srcPath = 'C:\Users\Administrator\Downloads\fDa3R.jpg'
$buildDir = 'C:\Users\Administrator\Trabajo\IA-companion-GS\build'
$assetsDir = 'C:\Users\Administrator\Trabajo\IA-companion-GS\src\renderer\assets'
New-Item -ItemType Directory -Force -Path $buildDir, $assetsDir | Out-Null

$src = New-Object System.Drawing.Bitmap($srcPath)
$w = $src.Width; $h = $src.Height
$rect = New-Object System.Drawing.Rectangle(0, 0, $w, $h)

# ---------- Leer bytes (BGRA) ----------
$data = $src.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$bytes = New-Object byte[] ($w * $h * 4)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)
$src.UnlockBits($data)

function Get-Spread([byte[]]$b, [int]$o, [ref]$lumOut) {
    $bl = $b[$o]; $g = $b[$o + 1]; $r = $b[$o + 2]
    $mx = [Math]::Max($r, [Math]::Max($g, $bl))
    $mn = [Math]::Min($r, [Math]::Min($g, $bl))
    $lumOut.Value = ($r + $g + $bl) / 3
    return ($mx - $mn)
}
function Test-Board([byte[]]$b, [int]$o) {
    $lum = 0
    $spread = Get-Spread $b $o ([ref]$lum)
    return (($spread -le 18) -and ($lum -ge 200))
}

# ---------- PASO 1: flood fill desde bordes ----------
$visited = New-Object bool[] ($w * $h)
$queue = New-Object 'System.Collections.Generic.Queue[int]'
for ($x = 0; $x -lt $w; $x++) {
    foreach ($y in @(0, ($h - 1))) {
        $i = $y * $w + $x
        if (-not $visited[$i] -and (Test-Board $bytes ($i * 4))) { $visited[$i] = $true; $queue.Enqueue($i) }
    }
}
for ($y = 0; $y -lt $h; $y++) {
    foreach ($x in @(0, ($w - 1))) {
        $i = $y * $w + $x
        if (-not $visited[$i] -and (Test-Board $bytes ($i * 4))) { $visited[$i] = $true; $queue.Enqueue($i) }
    }
}
while ($queue.Count -gt 0) {
    $i = $queue.Dequeue()
    $bytes[($i * 4) + 3] = 0
    $x = $i % $w; $y = [Math]::Floor($i / $w)
    foreach ($n in @(@(($x - 1), $y), @(($x + 1), $y), @($x, ($y - 1)), @($x, ($y + 1)))) {
        $nx = $n[0]; $ny = $n[1]
        if ($nx -ge 0 -and $nx -lt $w -and $ny -ge 0 -and $ny -lt $h) {
            $ni = $ny * $w + $nx
            if (-not $visited[$ni] -and (Test-Board $bytes ($ni * 4))) { $visited[$ni] = $true; $queue.Enqueue($ni) }
        }
    }
}
Write-Host "PASO 1 flood fill OK"

# ---------- PASO 2: detectar nucleo (componente casi-blanco mas grande) ----------
$label = New-Object int[] ($w * $h)
$comps = New-Object 'System.Collections.Generic.List[object]'
function Test-NucleusPx([byte[]]$b, [int]$o) {
    $lum = 0
    $spread = Get-Spread $b $o ([ref]$lum)
    $bl = $b[$o]; $r = $b[$o + 2]
    return (($spread -le 12) -and ($lum -ge 244) -and ([Math]::Abs($bl - $r) -le 18))
}
$nq = New-Object 'System.Collections.Generic.Queue[int]'
$nl = 0
for ($i = 0; $i -lt ($w * $h); $i++) {
    if ($label[$i] -eq 0 -and (Test-NucleusPx $bytes ($i * 4))) {
        $nl++
        $label[$i] = $nl
        $nq.Enqueue($i)
        $count = 0; $sx = 0L; $sy = 0L
        $minX = $w; $minY = $h; $maxX = 0; $maxY = 0
        while ($nq.Count -gt 0) {
            $j = $nq.Dequeue(); $count++
            $jx = $j % $w; $jy = [Math]::Floor($j / $w)
            $sx += $jx; $sy += $jy
            if ($jx -lt $minX) { $minX = $jx }; if ($jx -gt $maxX) { $maxX = $jx }
            if ($jy -lt $minY) { $minY = $jy }; if ($jy -gt $maxY) { $maxY = $jy }
            foreach ($n in @(@(($jx - 1), $jy), @(($jx + 1), $jy), @($jx, ($jy - 1)), @($jx, ($jy + 1)))) {
                $nx = $n[0]; $ny = $n[1]
                if ($nx -ge 0 -and $nx -lt $w -and $ny -ge 0 -and $ny -lt $h) {
                    $nj = $ny * $w + $nx
                    if ($label[$nj] -eq 0 -and (Test-NucleusPx $bytes ($nj * 4))) { $label[$nj] = $nl; $nq.Enqueue($nj) }
                }
            }
        }
        [void]$comps.Add(@{ count = $count; cx = ($sx / $count); cy = ($sy / $count); minX = $minX; minY = $minY; maxX = $maxX; maxY = $maxY })
    }
}
$big = $null; $best = 0
foreach ($c in $comps) { if ($c.count -gt $best) { $best = $c.count; $big = $c } }
$ncx = $big.cx; $ncy = $big.cy; $nr = [Math]::Sqrt($big.count / [Math]::PI)
Write-Host ("nucleo: centro=({0:N0},{1:N0}) radio~{2:N1} px ({3} px), comps={4}" -f $ncx, $ncy, $nr, $big.count, $comps.Count)

# ---------- PASO 2.5: radio de la orbita (histograma radial de pixeles blanco-neutros) ----------
$bins = New-Object int[] 400
for ($y = [int]($ncy - 300); $y -lt [int]($ncy + 300); $y++) {
    if ($y -lt 0 -or $y -ge $h) { continue }
    for ($x = [int]($ncx - 300); $x -lt [int]($ncx + 300); $x++) {
        if ($x -lt 0 -or $x -ge $w) { continue }
        $i = $y * $w + $x
        if ($label[$i] -ne 0) { continue }  # dentro del nucleo
        if ($bytes[($i * 4) + 3] -eq 0) { continue }
        $lum = 0
        $spread = Get-Spread $bytes ($i * 4) ([ref]$lum)
        $bl = $bytes[($i * 4)]; $r = $bytes[($i * 4) + 2]
        if (($lum -ge 225) -and ([Math]::Abs($bl - $r) -le 35) -and (($r - $g0) -eq 0)) {}
        if (($lum -ge 225) -and ([Math]::Abs($bl - $r) -le 35)) {
            $d = [Math]::Sqrt([Math]::Pow($x - $ncx, 2) + [Math]::Pow($y - $ncy, 2))
            $bin = [int][Math]::Floor($d)
            if ($bin -ge 0 -and $bin -lt 400) { $bins[$bin]++ }
        }
    }
}
# buscar banda de la orbita: bin con pico fuera del radio del nucleo+glow
$rStart = [int]($nr + 10)
$peakBin = $rStart; $peakVal = 0
for ($b = $rStart; $b -lt 350; $b++) { if ($bins[$b] -gt $peakVal) { $peakVal = $bins[$b]; $peakBin = $b } }
Write-Host "orbita: pico radial en $peakBin px (valor $($peakVal))"
$orbitR = $peakBin

# ---------- PASO 3: limpieza por periodicidad (tablero residual; preserva halo cian) ----------
$cleaned = 0
for ($y = 0; $y -lt $h; $y++) {
    for ($x = 0; $x -lt $w; $x++) {
        $i = $y * $w + $x
        if ($bytes[($i * 4) + 3] -eq 0) { continue }
        $lum = 0
        $spread = Get-Spread $bytes ($i * 4) ([ref]$lum)
        if ($spread -gt 45 -or $lum -lt 180) { continue }
        $bl = $bytes[($i * 4)]; $r = $bytes[($i * 4) + 2]
        if ([Math]::Abs($bl - $r) -gt 30) { continue }
        $isChecker = $false
        if ($y + 8 -lt $h) {
            $lum2 = 0
            [void](Get-Spread $bytes ((($y + 8) * $w + $x) * 4) ([ref]$lum2))
            if ([Math]::Abs($lum - $lum2) -gt 12) { $isChecker = $true }
        }
        if (-not $isChecker -and $y - 8 -ge 0) {
            $lum2 = 0
            [void](Get-Spread $bytes ((($y - 8) * $w + $x) * 4) ([ref]$lum2))
            if ([Math]::Abs($lum - $lum2) -gt 12) { $isChecker = $true }
        }
        if ($isChecker) { $bytes[($i * 4) + 3] = 0; $cleaned++ }
    }
}
Write-Host "PASO 3 periodicidad: $cleaned limpiados"

# ---------- PASO 4: barrido de residuos vecinos a zona limpiada ----------
for ($pass = 0; $pass -lt 3; $pass++) {
    $removed = 0
    $snapshot = New-Object byte[] ($w * $h * 4)
    [Array]::Copy($bytes, $snapshot, $bytes.Length)
    for ($y = 1; $y -lt $h - 1; $y++) {
        for ($x = 1; $x -lt $w - 1; $x++) {
            $i = $y * $w + $x
            if ($snapshot[($i * 4) + 3] -eq 0) { continue }
            $lum = 0
            $spread = Get-Spread $snapshot ($i * 4) ([ref]$lum)
            if ($spread -gt 45 -or $lum -lt 180 -or $lum -gt 252) { continue }
            $bl = $snapshot[($i * 4)]; $r = $snapshot[($i * 4) + 2]
            if ([Math]::Abs($bl - $r) -gt 30) { continue }
            $clean neighbors = 0
            $cn = 0
            foreach ($n in @((($x - 1) + $y * $w), ((($x + 1)) + $y * $w), ($x + ($y - 1) * $w), ($x + ($y + 1) * $w))) {
                if ($snapshot[($n * 4) + 3] -eq 0) { $cn++ }
            }
            if ($cn -ge 2) { $bytes[($i * 4) + 3] = 0; $removed++ }
        }
    }
    Write-Host "PASO 4 iter $pass: $removed"
    if ($removed -eq 0) { break }
}

# ---------- PASO 5: redibujar la orbita (elipse de anillo + 4 nodos) ----------
# Trabajamos sobre el bitmap final con alfa
$outBmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$odata = $outBmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::WriteOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
[System.Runtime.InteropServices.Marshal]::Copy($bytes, 0, $odata.Scan0, $bytes.Length)
$outBmp.UnlockBits($odata)

$g = [System.Drawing.Graphics]::FromImage($outBmp)
$g.SmoothingMode = 'AntiAlias'
# elipse inclinada como el diseño original: semieje mayor perpendicular (rotation -25)
$g.TranslateTransform([float]$ncx, [float]$ncy)
$g.RotateTransform(-25.0)
$ellW = $orbitR * 2.0 * 0.92
$ellH = $orbitR * 2.0 * 1.08
$pen = New-Object System.Drawing.Pen ([System.Drawing.Color]::FromArgb(215, 255, 255, 255)), 3.0
$g.DrawEllipse($pen, [float](-$ellW / 2), [float](-$ellH / 2), [float]$ellW, [float]$ellH)
$dotR = [Math]::Max(6.0, $nr * 0.30)
$dotBrush = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(235, 255, 255, 255))
foreach ($t in @(50, 130, 230, 310)) {
    $a = $t * [Math]::PI / 180.0
    $dx = ($ellW / 2.0) * [Math]::Cos($a)
    $dy = ($ellH / 2.0) * [Math]::Sin($a)
    $g.FillEllipse($dotBrush, [float]($dx - $dotR), [float]($dy - $dotR), [float]($dotR * 2), [float]($dotR * 2))
}
$g.ResetTransform()
$g.Dispose()
$outBmp.Save("$buildDir\ia-logo-full.png", [System.Drawing.Imaging.ImageFormat]::Png)

# ---------- Bounding box + separador mark/wordmark ----------
$bytes2 = New-Object byte[] ($w * $h * 4)
$data2 = $outBmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
[System.Runtime.InteropServices.Marshal]::Copy($data2.Scan0, $bytes2, 0, $bytes2.Length)
$outBmp.UnlockBits($data2)

$rowCounts = New-Object int[] $h
$minX = $w; $minY = $h; $maxX = 0; $maxY = 0
for ($y = 0; $y -lt $h; $y++) {
    $c = 0
    for ($x = 0; $x -lt $w; $x++) {
        if ($bytes2[($y * $w + $x) * 4 + 3] -gt 8) { $c++ }
    }
    $rowCounts[$y] = $c
    if ($c -gt 0) {
        if ($y -lt $minY) { $minY = $y }; if ($y -gt $maxY) { $maxY = $y }
    }
}
for ($x = 0; $x -lt $w; $x++) {
    for ($y = $minY; $y -le $maxY; $y++) {
        if ($bytes2[($y * $w + $x) * 4 + 3] -gt 8) { if ($x -lt $minX) { $minX = $x }; if ($x -gt $maxX) { $maxX = $x }; break }
    }
    for ($y = $maxY; $y -ge $minY; $y--) {
        if ($bytes2[($y * $w + $x) * 4 + 3] -gt 8) { if ($x -lt $minX) { $minX = $x }; if ($x -gt $maxX) { $maxX = $x }; break }
    }
}
$bestStart = -1; $bestLen = 0; $curStart = -1
for ($y = $minY; $y -le $maxY; $y++) {
    if ($rowCounts[$y] -lt 3) {
        if ($curStart -lt 0) { $curStart = $y }
    } else {
        if ($curStart -ge 0) {
            $len = $y - $curStart
            if ($len -gt $bestLen) { $bestLen = $len; $bestStart = $curStart }
            $curStart = -1
        }
    }
}
if ($bestLen -gt 5) { $markBottom = $bestStart - 1 } else { $markBottom = $maxY }
Write-Host "bbox: x=$minX..$maxX y=$minY..$maxY; mark termina en $markBottom"

function Save-Cropped([System.Drawing.Bitmap]$bitmap, [int]$cx, [int]$cy, [int]$cw, [int]$ch, [string]$outPath, [int]$outSize) {
    $square = [Math]::Max($cw, $ch)
    $out = New-Object System.Drawing.Bitmap($outSize, $outSize)
    $g = [System.Drawing.Graphics]::FromImage($out)
    $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $g.SmoothingMode = 'AntiAlias'
    $g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
    $scale = $outSize / $square
    $dstW = [Math]::Round($cw * $scale); $dstH = [Math]::Round($ch * $scale)
    $dstX = [Math]::Round((($square - $cw) / 2.0) * $scale); $dstY = [Math]::Round((($square - $ch) / 2.0) * $scale)
    $g.DrawImage($bitmap,
        (New-Object System.Drawing.Rectangle($dstX, $dstY, $dstW, $dstH)),
        (New-Object System.Drawing.Rectangle($cx, $cy, $cw, $ch)),
        [System.Drawing.GraphicsUnit]::Pixel)
    $g.Dispose()
    $out.Save($outPath, [System.Drawing.Imaging.ImageFormat]::Png)
    $out.Dispose()
}

$markH = $markBottom - $minY + 1
$markW = $maxX - $minX + 1
if ($markH -gt 0) {
