$hicon = $iconBmp.GetHicon()
$icon = [System.Drawing.Icon]::FromHandle($hicon)
$fs = [System.IO.File]::Create("$buildDir\icon.ico")
$icon.Save($fs)
$fs.Dispose()
$icon.Dispose(); $iconBmp.Dispose()

# logo completo 320px para Acerca de
$s = 320.0 / $w
$outFull = New-Object System.Drawing.Bitmap(320, [int]($h * $s))
$gf = [System.Drawing.Graphics]::FromImage($outFull)
$gf.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
$gf.SmoothingMode = 'AntiAlias'
$gf.DrawImage($outBmp, (New-Object System.Drawing.Rectangle(0, 0, $outFull.Width, $outFull.Height)), (New-Object System.Drawing.Rectangle(0, 0, $w, $h)), [System.Drawing.GraphicsUnit]::Pixel)
$gf.Dispose()
$outFull.Save("$assetsDir\logo.png", [System.Drawing.Imaging.ImageFormat]::Png)
$outFull.Dispose()

$src.Dispose()
$outBmp.Dispose()
Write-Host "OK"

