# buscar banda de la orbita: pixel blanco-neutro en radio alejado del nucleo+glow
$rStart = 70
$peakBin = $rStart; $peakVal = 0
for ($b = $rStart; $b -lt 260; $b++) { if ($bins[$b] -gt $peakVal) { $peakVal = $bins[$b]; $peakBin = $b } }
Write-Host "orbita: pico radial en $peakBin px (valor $($peakVal))"
$orbitR = $peakBin

# semi-ejes e inclinacion: momentos de los pixeles de la banda |r-orbitR|<=12
$bandPixels = New-Object 'System.Collections.Generic.List[object]'
for ($y = [int]($ncy - 260); $y -lt [int]($ncy + 260); $y++) {
    if ($y -lt 0 -or $y -ge $h) { continue }
    for ($x = [int]($ncx - 260); $x -lt [int]($ncx + 260); $x++) {
        if ($x -lt 0 -or $x -ge $w) { continue }
        $i = $y * $w + $x
        if ($label[$i] -ne 0) { continue }
        if ($bytes[($i * 4) + 3] -eq 0) { continue }
        $lum = 0
        $spread = Get-Spread $bytes ($i * 4) ([ref]$lum)
        $bl = $bytes[($i * 4)]; $r = $bytes[($i * 4) + 2]
        if (($lum -ge 225) -and ([Math]::Abs($bl - $r) -le 35)) {
            $d = [Math]::Sqrt([Math]::Pow($x - $ncx, 2) + [Math]::Pow($y - $ncy, 2))
            if ([Math]::Abs($d - $orbitR) -le 12) {
                $ang = [Math]::Atan2($y - $ncy, $x - $ncx) * 180.0 / [Math]::PI
                if ($ang -lt 0) { $ang += 360 }
                [void]$bandPixels.Add(@{ angle = [int][Math]::Floor($ang / 10) * 10; r = $d })
            }
        }
    }
}
$a = $orbitR * 1.07; $bsemi = $orbitR * 0.93; $phi = -25.0
if ($bandPixels.Count -ge 30) {
    $maxR = 0.0; $minR = 999.0; $angAtMax = -25.0
    $bucketSum = @{}; $bucketCnt = @{}
    foreach ($bp in $bandPixels) {
        if ($bp.r -gt $maxR) { $maxR = $bp.r; $angAtMax = $bp.angle }
        if ($bp.r -lt $minR) { $minR = $bp.r }
    }
    if ($maxR -gt $minR + 4) {
        $a = $maxR; $bsemi = [Math]::Max($minR, $orbitR * 0.90); $phi = $angAtMax
    }
}
Write-Host ("orbita fit: a={0:N1} b={1:N1} phi={2:N0}" -f $a, $bsemi, $phi)

